    "justification": "Expression profiling was performed on human samples using Affymetrix microarrays (U133A)."
  },
  "q2_target_disease": {
    "answer": "No",
    "evidence": "Title/Description: 'Gene expression patterns in peripheral blood correlate with the extent of coronary artery disease'; Experimental factors include CADI and patient groups with CAD vs controls.",
    "justification": "The study focuses on coronary artery disease (CAD), not amyotrophic lateral sclerosis or frontotemporal dementia."
  },
  "q3_human_cns_tissue": {
    "answer": "No",
    "evidence": "Description: RNA extracted from circulating leukocytes (peripheral blood); Organism: Homo sapiens; Organism part: not brain/CNS.",
    "justification": "Samples are peripheral blood leukocytes, not human brain or CNS tissue."
  },
  "q4_non_clinical": {
    "answer": "No",
    "evidence": "Description: RNA extracted from patient circulating leukocytes obtained during coronary angiography; no mention of cell lines or model systems.",
    "justification": "Samples are primary patient blood cells, not patient-derived in vitro cell lines or experimental disease models."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "Description: RNA from 110 patients with CAD (CADi>23) and 112 partially matched controls without CAD (CADi=0); 'parallel group design'.",
    "justification": "The study compares cases (CAD patients) to controls, fitting a case/control design, albeit for CAD."
  },
  "q6_irrelevant_brain_region": {
    "answer": "Yes",
    "evidence": "Samples are peripheral blood leukocytes (no brain regions sampled).",
    "justification": "No CNS regions were assayed; peripheral blood is not a brain region affected by ALS-FTD, so sampled tissue is irrelevant to ALS-FTD neurodegeneration."
  },
  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Technology: Array assay; Affymetrix U133A microarrays reported.",
    "justification": "The assay is microarray-based (compatible). No RNA-seq or proteomics technologies reported."
  },
  "q8_inclusion_justification": {
    "justification": "Although this is a human microarray case/control study, it targets coronary artery disease and uses peripheral blood leukocytes rather than CNS tissue relevant to ALS-FTD. Therefore it fails the disease- and tissue-related inclusion criteria."
  },
  "q9_include_dataset": {
    "answer": "No"
  }
}

